<?php $profile = $profile ?? []; $metrics = $profile['metrics'] ?? []; $recommendation = $profile['recommendation'] ?? []; $riskLabels = ['low' => 'کم', 'medium' => 'متوسط', 'high' => 'زیاد']; ?>
<section class="card">
  <div class="card-header"><div class="header-top"><div><h2><?= e($profile['customer']['full_name'] ?? '') ?> — Proma Score</h2><p>پروفایل ریسک بر مبنای سوابق واقعی ثبت‌شده</p></div><a class="btn secondary" href="<?= e(url('risk')) ?>">بازگشت</a></div></div>
  <div class="card-body">
    <div class="risk-score-panel"><strong><?= to_persian_digits($profile['score'] ?? 0) ?><small> / ۱۰۰۰</small></strong><span class="badge <?= e($profile['risk_level'] ?? 'medium') ?>">ریسک <?= e($riskLabels[$profile['risk_level'] ?? 'medium'] ?? 'نامشخص') ?></span></div>
    <div class="kpi-grid">
      <?php foreach ([['قرارداد موفق', $metrics['successful_contracts'] ?? 0], ['اعتبار اخذشده', number_format($metrics['credit_volume_toman'] ?? 0) . ' تومان'], ['پرداخت به‌موقع', isset($metrics['on_time_rate']) ? $metrics['on_time_rate'] . '٪' : 'بدون سابقه'], ['میانگین تأخیر', ($metrics['average_delay_days'] ?? 0) . ' روز'], ['پروندهٔ حقوقی باز', $metrics['open_legal_cases'] ?? 0], ['وعدهٔ گذشته، برآوردی', $metrics['broken_promises_estimated'] ?? 0], ['بدهی جاری', $metrics['current_debt_toman'] === null ? 'نیازمند بررسی' : number_format($metrics['current_debt_toman']) . ' تومان']] as [$label,$value]): ?><article class="kpi-card"><span><?= e($label) ?></span><strong><?= e((string) $value) ?></strong></article><?php endforeach; ?>
    </div>
    <section class="risk-details"><h3>دلایل امتیاز</h3><?php foreach (($profile['reasons'] ?? []) as $reason): ?><div class="risk-reason"><span><?= e($reason['label'] ?? '') ?></span><strong class="<?= (int) ($reason['points'] ?? 0) < 0 ? 'text-danger' : 'text-success' ?>"><?= ((int) ($reason['points'] ?? 0) > 0 ? '+' : '') . to_persian_digits((int) ($reason['points'] ?? 0)) ?></strong></div><?php endforeach; ?></section>
    <section class="risk-details"><h3>پیشنهاد اعتبار (تصمیم نهایی با مدیر)</h3><div class="risk-reason"><span>سقف پیشنهادی</span><strong><?= to_persian_digits(number_format($recommendation['credit_limit_toman'] ?? 0)) ?> تومان</strong></div><div class="risk-reason"><span>پیش‌پرداخت</span><strong><?= to_persian_digits($recommendation['down_payment_percent'] ?? 0) ?>٪</strong></div><div class="risk-reason"><span>حداکثر دوره</span><strong><?= to_persian_digits($recommendation['max_term_months'] ?? 0) ?> ماه</strong></div><div class="risk-reason"><span>ضامن</span><strong><?= !empty($recommendation['guarantor_required']) ? 'پیشنهاد می‌شود' : 'ضروری نیست' ?></strong></div></section>
    <div class="notice info"><?= e($profile['returned_checks_note'] ?? '') ?> امتیاز، پیشنهاد مالی خودکار یا رد درخواست نیست.</div>
  </div>
</section>
